import { Group } from '@visx/group';
import React, { PropsWithChildren, useContext } from 'react';
import styled from 'styled-components';

import Colors from '@dynatrace/strato-design-tokens/colors';
import Typography from '@dynatrace/strato-design-tokens/typography';

import { MarkersRenderer } from './MarkersRenderer.js';
import { TextEllipsis } from '../../../../../typography/TextEllipsis.js';
import {
  MARKER_RADIUS,
  LABEL_TEXT_HEIGHT,
  LABEL_OFFSET,
} from '../constants.js';
import { AnnotationsContext } from '../context.js';

/**
 * @internal
 * Props for TrackAtom, representing properties related to a track.
 */
export interface TrackAtomProps {
  /** Optional label for the track. */
  label?: string;
  /** Optional callback when the mouse enters the track. */
  onMouseEnter?: (event: React.MouseEvent) => void;

  /** Whether this track should be visible */
  hidden?: boolean;
}

interface LabelProps {
  width: number;
}

const Label = /* @__PURE__ */ styled('span')<LabelProps>(({ width }) => ({
  width: `${width}px`,
  fontFamily: `${Typography.Text.Small.Emphasized.Family}`,
  fontSize: `${Typography.Text.Small.Emphasized.Size}`,
  color: `${Colors.Text.Neutral.Subdued}`,
  textAlign: 'right',
  display: 'block',
}));

/**
 * @internal
 * The Track atomic component
 **/
export const TrackAtom = ({
  label,
  onMouseEnter,
  children,
}: PropsWithChildren<TrackAtomProps>) => {
  const { showLabels, labelsWidth: labelsWidthProp } =
    useContext(AnnotationsContext);

  const labelWidth = labelsWidthProp - MARKER_RADIUS;
  const markersOffset = labelsWidthProp + MARKER_RADIUS;

  return (
    <>
      {showLabels && label && (
        <foreignObject
          height={LABEL_TEXT_HEIGHT}
          width={labelWidth}
          x={LABEL_OFFSET}
          y={LABEL_OFFSET}
        >
          <Label width={labelWidth}>
            <TextEllipsis truncationMode={'end'}>{label}</TextEllipsis>
          </Label>
        </foreignObject>
      )}
      <Group
        transform={`translate(${markersOffset},0)`}
        onMouseEnter={onMouseEnter}
      >
        <MarkersRenderer>{children}</MarkersRenderer>
      </Group>
    </>
  );
};

TrackAtom['displayName'] = 'Annotations.TrackAtom';
